function softmax(arr) {const max = Math.max(...arr); const exps = arr.map(x => Math.exp(x - max)); const sum = exps.reduce((a, b) => a + b, 0);  return exps.map(v => v / sum);}
function shuffle(array) {for (let i = array.length - 1; i > 0; i--) {const j = Math.floor(Math.random() * (i + 1));[array[i], array[j]] = [array[j], array[i]];}return array;}
function getInput() {let input = []; document.querySelectorAll('.cube').forEach(cube => {let [r, g, b] = getComputedStyle(cube).backgroundColor.match(/\d+/g).map(Number); let avg = (r + g + b) / 3; input.push(avg / 255)}); return input}
function clearBoard() {document.querySelectorAll('.cube').forEach(cube => {cube.style.backgroundColor = `rgb(255, 255, 255)`})}
function forwardPropagation(input) {if (!input) input = centerImage(getInput());let output = []; let preAct = []; wab.forEach((layer, index) => {let l = []; let preActL = [];let sum; layer.forEach(neural => {sum = 0; for(let k=0;k<neural.weights.length;k++) {sum += index === 0 ? input[k] * neural.weights[k]: output[output.length-1][k] * neural.weights[k]}sum += neural.bias; preActL.push(sum); sum = index !== wab.length - 1 ? relu(sum) : sum; l.push(sum)}); l = index === wab.length - 1 ? softmax(l) : l; output.push(l); preAct.push(preActL)}); return [output, preAct]}
function predictBest() {let output = forwardPropagation()[0].at(-1).map((v, i) => ({value: v, idx: i})).sort((a,b) => b.value - a.value); let bestPos = output[0]; let secPos = output[1]; alert(`i think its: ${bestPos.idx} at ${(bestPos.value * 100).toFixed(2)}%\n\nOR\n\nit might be ${secPos.idx} at ${(secPos.value * 100).toFixed(2)}%`)} 
function centerImage(image) {const size = Math.sqrt(image.length); let rows = []; const whiteArray = Array(size).fill(1); for (let i=0;i<image.length;i += size) {rows.push(image.slice(i, i+size))}; for(let r=rows.length-1;r>=0;r--) {if (arrayEquals(rows[r], whiteArray)) {rows.splice(r, 1)}}const missingRows = size - rows.length; const topArray = Array.from({length: missingRows % 2 === 0 ? missingRows / 2 : missingRows / 2 +0.5}, () => Array(size).fill(1)); const bottomArray = Array.from({length: missingRows % 2 === 0 ? missingRows / 2 : missingRows / 2 - 0.5}, () => Array(size).fill(1));const fixedRows = topArray.concat(rows).concat(bottomArray).flat(); let cols = []; for (let a=0;a<size;a++) {let layer = [];for (i=0+a;i<fixedRows.length;i += size) {layer.push(fixedRows[i])}cols.push(layer)}for (let c=cols.length-1;c>=0;c--) {if (arrayEquals(cols[c], whiteArray)) {cols.splice(c, 1)}}const missingCols = size - cols.length; const leftArray = Array.from({length: missingCols % 2 === 0 ? missingCols / 2 : missingCols / 2 + 0.5}, () => Array(size).fill(1)); const rightArray = Array.from({length: missingCols % 2 === 0 ? missingCols / 2 : missingCols / 2 - 0.5}, () => Array(size).fill(1));const fixedImageA = leftArray.concat(cols).concat(rightArray).flat(); let fixedImage = []; for (let a=0;a<size;a++) {let layer = []; for (i=0+a;i<fixedImageA.length;i += size) {layer.push(fixedImageA[i])};fixedImage.push(layer)};fixedImage = fixedImage.flat();return fixedImage}
function arrayEquals(a, b) {return a.length === b.length && a.every((v, i) => v === b[i])}
function relu(x) {return Math.max(x, 0)}
